"""Mini spreadsheet engine."""
import re

CELL_RE = re.compile(r"[A-Z][1-9]\d{0,2}")
INT_RE = re.compile(r"-?\d+")
FLOAT_RE = re.compile(r"-?\d+\.\d+")

TOKEN_RE = re.compile(
    r"\s*(?:"
    r"(?P<num>\d+(?:\.\d+)?)"
    r"|(?P<ref>(?P<col>[A-Z])(?P<row>\d+))"
    r"|(?P<op>[-+*/()])"
    r")"
)


def _check_cell(cell):
    if not isinstance(cell, str) or not CELL_RE.fullmatch(cell):
        raise ValueError(f"invalid cell name: {cell!r}")


class ParseError(Exception):
    pass


def tokenize(text):
    tokens = []
    pos = 0
    while True:
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos == len(text):
            break
        m = TOKEN_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ParseError(f"bad token at {pos}")
        if m.group("num"):
            s = m.group("num")
            tokens.append(("num", float(s) if "." in s else int(s)))
        elif m.group("ref"):
            tokens.append(("ref", (m.group("col"), int(m.group("row")))))
        else:
            tokens.append(("op", m.group("op")))
        pos = m.end()
    return tokens


class Parser:
    """Recursive descent parser producing a tuple-based AST."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise ParseError(f"expected {op}")

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise ParseError("trailing tokens")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            return ("ref", val)
        if (kind, val) == ("op", "("):
            node = self.expr()
            self.expect_op(")")
            return node
        raise ParseError("unexpected token")


def parse_formula(raw):
    return Parser(tokenize(raw[1:])).parse()


class Sheet:
    def __init__(self):
        self._raw = {}

    def set(self, cell, raw):
        _check_cell(cell)
        if raw == "":
            self._raw.pop(cell, None)
        else:
            self._raw[cell] = raw

    def raw(self, cell):
        _check_cell(cell)
        return self._raw.get(cell, "")

    def get(self, cell):
        _check_cell(cell)
        return self._value(cell)

    def _value(self, cell):
        raw = self._raw.get(cell)
        if raw is None:
            return None
        if INT_RE.fullmatch(raw):
            return int(raw)
        if FLOAT_RE.fullmatch(raw):
            return float(raw)
        if raw.startswith("="):
            return self._eval(parse_formula(raw))
        return raw

    def _eval(self, node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            col, row = node[1]
            v = self._value(f"{col}{row}")
            return 0 if v is None else v
        if kind == "neg":
            return -self._eval(node[1])
        _, op, l, r = node
        a, b = self._eval(l), self._eval(r)
        if op == "+":
            return a + b
        if op == "-":
            return a - b
        if op == "*":
            return a * b
        return a / b
