from solution import Sheet


def mk(**cells):
    s = Sheet()
    for k, v in cells.items():
        s.set(k, v)
    return s


def test_div_zero():
    s = mk(A1="=1/0", A2="=1/B1", A3="=1/0.0", A4="=0/0")
    assert s.get("A1") == "#DIV/0!"
    assert s.get("A2") == "#DIV/0!"
    assert s.get("A3") == "#DIV/0!"
    assert s.get("A4") == "#DIV/0!"


def test_text_in_arithmetic():
    s = mk(A1="hello", B1="=A1+1", B2="=-A1", B3="=2*A1", B4="=A1/1")
    for c in ("B1", "B2", "B3", "B4"):
        assert s.get(c) == "#VALUE!"


def test_bare_text_reference_is_not_arithmetic():
    s = mk(A1="hello", B1="=A1")
    assert s.get("B1") == "hello"


def test_error_propagation():
    s = mk(A1="=1/0", B1="=A1+1", C1="=B1*2", D1="=-A1")
    assert s.get("B1") == "#DIV/0!"
    assert s.get("C1") == "#DIV/0!"
    assert s.get("D1") == "#DIV/0!"


def test_left_error_wins():
    s = mk(A1="=1/0", A2="x", A3="=A2+1", B1="=A1+A3", B2="=A3+A1")
    assert s.get("B1") == "#DIV/0!"
    assert s.get("B2") == "#VALUE!"


def test_error_beats_text():
    s = mk(A1="text", A2="=1/0", B1="=A1+A2")
    assert s.get("B1") == "#DIV/0!"


def test_parse_errors():
    for f in ["=", "=1+", "=(1", "=1)", "=1 2", "=a1", "=A", "=1..2", "=foo", "=1+*2", "=A1B"]:
        s = mk(A1=f)
        assert s.get("A1") == "#VALUE!", f
        assert s.raw("A1") == f


def test_error_string_as_text_is_error_value():
    s = mk(A1="#DIV/0!", B1="=A1+1")
    assert s.get("B1") == "#DIV/0!"
