                    parent = work[-1][0]
                    low[parent] = min(low[parent], low[node])
                if low[node] == index[node]:
                    scc = []
                    while True:
                        c = stack.pop()
                        on_stack.discard(c)
                        scc.append(c)
                        if c == node:
                            break
                    yield scc

