        counter = 0
        for root in self._raw:
            if root in index:
                continue
            work = [(root, iter(self._deps(root)))]
            index[root] = low[root] = counter
            counter += 1
            stack.append(root)
            on_stack.add(root)
            while work:
                node, it = work[-1]
                advanced = False
                for dep in it:
                    if dep not in index:
                        index[dep] = low[dep] = counter
                        counter += 1
                        stack.append(dep)
                        on_stack.add(dep)
                        work.append((dep, iter(self._deps(dep))))
                        advanced = True
                        break
                    if dep in on_stack:
                        low[node] = min(low[node], index[dep])
                if advanced:
                    continue
                work.pop()
                if work:
                    parent = work[-1][0]
                    low[parent] = min(low[parent], low[node])
                if low[node] == index[node]:
                    scc = []
                    while True:
                        c = stack.pop()
                        on_stack.discard(c)
                        scc.append(c)
                        if c == node:
                            break
                    yield scc

    def _recalc(self):
        self._values = {}
        for scc in self._order():
