        if tree is None:
            return VALUE
        return self._eval(tree)

    def _eval(self, node):
        kind = node[0]
        if kind in ("num", "err"):
            return node[1]
        if kind == "ref":
            col, row = node[1]
            v = self._values.get(f"{col}{row}")
            return 0 if v is None else v
        if kind == "neg":
            v = self._eval(node[1])
            if _is_error(v):
                return v
            if isinstance(v, str):
                return VALUE
            return -v
        if kind == "func":
            return self._call(node[1], node[2])
        _, op, l, r = node
        return _binop(op, self._eval(l), self._eval(r))

    def _call(self, name, args):
        nums = []
        for arg in args:
            if arg[0] == "range":
                for c in _range_cells(arg[1], arg[2]):
                    v = self._values.get(c)
                    if _is_error(v):
