"""Mini spreadsheet engine."""
import re

CELL_RE = re.compile(r"[A-Z][1-9]\d{0,2}")
INT_RE = re.compile(r"-?\d+")
FLOAT_RE = re.compile(r"-?\d+\.\d+")

DIV0 = "#DIV/0!"
VALUE = "#VALUE!"
REF = "#REF!"
CYCLE = "#CYCLE!"
ERRORS = frozenset({DIV0, VALUE, REF, CYCLE})
FUNCTIONS = frozenset({"SUM", "MIN", "MAX", "AVG", "COUNT"})

MAX_ROW = 999
REF_PATTERN = r"(?P<cabs>\$?)(?P<col>[A-Z])(?P<rabs>\$?)(?P<row>\d+)"
REF_RE = re.compile(REF_PATTERN)
TOKEN_RE = re.compile(
    r"\s*(?:"
    r"(?P<num>\d+(?:\.\d+)?)"
    r"|(?P<ref>" + REF_PATTERN + r")"
    r"|(?P<ident>[A-Z]+)"
    r"|(?P<err>#REF!)"
    r"|(?P<op>[-+*/(),:])"
    r")"
)


def _check_cell(cell):
    if not isinstance(cell, str) or not CELL_RE.fullmatch(cell):
        raise ValueError(f"invalid cell name: {cell!r}")


def _check_rows(at, n):
    if not (isinstance(at, int) and isinstance(n, int) and 1 <= at <= MAX_ROW and n >= 0):
        raise ValueError(f"invalid row arguments: at={at!r}, n={n!r}")


class ParseError(Exception):
    pass


def tokenize(text):
    tokens = []
    pos = 0
    while True:
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos == len(text):
            break
        m = TOKEN_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ParseError(f"bad token at {pos}")
        if m.group("num"):
            s = m.group("num")
            tokens.append(("num", float(s) if "." in s else int(s)))
        elif m.group("ref"):
            tokens.append(("ref", (m.group("col"), int(m.group("row")))))
        elif m.group("ident"):
            tokens.append(("ident", m.group("ident")))
        elif m.group("err"):
            tokens.append(("err", REF))
        else:
            tokens.append(("op", m.group("op")))
        pos = m.end()
    return tokens


class Parser:
    """Recursive descent parser producing a tuple-based AST."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise ParseError(f"expected {op}")

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise ParseError("trailing tokens")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            return ("ref", val) if _row_ok(val[1]) else ("err", REF)
        if kind == "err":
            return ("err", val)
        if kind == "ident":
            if val not in FUNCTIONS:
                raise ParseError(f"unknown function {val}")
