def rewrite_refs(formula, on_ref, on_range):
    """Rewrite every reference in `formula` in place.

    `on_ref(ref)` and `on_range(ref1, ref2)` receive parsed references
    (cabs, col, rabs, row). `on_ref` returns a new ref or None; `on_range`
    returns a pair of new refs or None. None becomes `#REF!` (a whole range
    collapses to a single `#REF!`). Everything else in the formula,
    including spacing around a range's colon, is preserved exactly.
