def _is_error(v):
    return isinstance(v, str) and v in ERRORS


def _binop(op, a, b):
    for v in (a, b):
        if _is_error(v):
            return v
    if isinstance(a, str) or isinstance(b, str):
        return VALUE
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
