        index, low, on_stack, stack = {}, {}, set(), []
        counter = 0
        for root in self._raw:
            if root in index:
                continue
            work = [(root, iter(self._deps(root)))]
            index[root] = low[root] = counter
            counter += 1
            stack.append(root)
            on_stack.add(root)
            while work:
                node, it = work[-1]
                advanced = False
                for dep in it:
                    if dep not in index:
