        if not m or m.end() == pos:
            raise ParseError(f"bad token at {pos}")
        if m.group("num"):
            s = m.group("num")
            tokens.append(("num", float(s) if "." in s else int(s)))
        elif m.group("ref"):
            tokens.append(("ref", (m.group("col"), int(m.group("row")))))
        elif m.group("ident"):
            tokens.append(("ident", m.group("ident")))
        elif m.group("err"):
            tokens.append(("err", REF))
        else:
            tokens.append(("op", m.group("op")))
        pos = m.end()
    return tokens


class Parser:
    """Recursive descent parser producing a tuple-based AST."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise ParseError(f"expected {op}")

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise ParseError("trailing tokens")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            return ("ref", val) if _row_ok(val[1]) else ("err", REF)
        if kind == "err":
            return ("err", val)
        if kind == "ident":
            if val not in FUNCTIONS:
                raise ParseError(f"unknown function {val}")
            self.expect_op("(")
            args = []
            if self.peek() != ("op", ")"):
                args.append(self.arg())
                while self.peek() == ("op", ","):
                    self.take()
                    args.append(self.arg())
            self.expect_op(")")
            return ("func", val, args)
        if (kind, val) == ("op", "("):
            node = self.expr()
            self.expect_op(")")
            return node
        raise ParseError("unexpected token")

    def arg(self):
        nxt = self.tokens[self.i + 1] if self.i + 1 < len(self.tokens) else None
        if self.peek()[0] == "ref" and nxt == ("op", ":"):
            a = self.take()[1]
            self.take()
            kind, b = self.take()
            if kind != "ref":
                raise ParseError("bad range")
            if not (_row_ok(a[1]) and _row_ok(b[1])):
                return ("err", REF)
            return ("range", a, b)
        return self.expr()


def _row_ok(row):
    return 1 <= row <= MAX_ROW


def parse_formula(raw):
    return Parser(tokenize(raw[1:])).parse()


def _split_cell(cell):
    return cell[0], int(cell[1:])


def rewrite_refs(formula, on_ref, on_range):
    """Rewrite every reference in `formula` in place.

    `on_ref(ref)` and `on_range(ref1, ref2)` receive parsed references
    (cabs, col, rabs, row). `on_ref` returns a new ref or None; `on_range`
    returns a pair of new refs or None. None becomes `#REF!` (a whole range
    collapses to a single `#REF!`). Everything else in the formula,
    including spacing around a range's colon, is preserved exactly.
    """
    out = []
    pos = 0
    n = len(formula)
    while pos < n:
        m = TOKEN_RE.match(formula, pos)
        if not m or m.end() == pos:
            out.append(formula[pos])
            pos += 1
            continue
        if not m.group("ref"):
            out.append(formula[pos:m.end()])
            pos = m.end()
            continue
        out.append(formula[pos:m.start("ref")])
        ref1 = _ref_parts(m)
        end1 = m.end()
        colon = re.compile(r"\s*:").match(formula, end1)
        m2 = TOKEN_RE.match(formula, colon.end()) if colon else None
        if m2 and m2.group("ref"):
            new = on_range(ref1, _ref_parts(m2))
            if new is None:
                out.append(REF)
            else:
                out.append(format_ref(new[0]))
                out.append(formula[end1:m2.start("ref")])
                out.append(format_ref(new[1]))
            pos = m2.end()
        else:
            new = on_ref(ref1)
            out.append(REF if new is None else format_ref(new))
            pos = end1
    return "".join(out)


def _ref_parts(m):
    return (m.group("cabs"), m.group("col"), m.group("rabs"), int(m.group("row")))


def format_ref(ref):
    cabs, col, rabs, row = ref
    return f"{cabs}{col}{rabs}{row}"


def _is_error(v):
    return isinstance(v, str) and v in ERRORS


def _binop(op, a, b):
    for v in (a, b):
        if _is_error(v):
            return v
    if isinstance(a, str) or isinstance(b, str):
        return VALUE
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return DIV0
    return a / b


def _literal(raw):
    """Value of a non-formula raw."""
    if INT_RE.fullmatch(raw):
        return int(raw)
    if FLOAT_RE.fullmatch(raw):
        return float(raw)
    return raw


def _range_cells(a, b):
    """Cells of a rectangle in row-major order; corners in any order."""
    (c1, r1), (c2, r2) = a, b
    cols = range(min(ord(c1), ord(c2)), max(ord(c1), ord(c2)) + 1)
    return [f"{chr(c)}{r}" for r in range(min(r1, r2), max(r1, r2) + 1) for c in cols]


def _refs(node, out):
    """Collect the cell names a formula AST references."""
    kind = node[0]
    if kind == "ref":
        col, row = node[1]
        out.add(f"{col}{row}")
    elif kind == "range":
        out.update(_range_cells(node[1], node[2]))
    elif kind == "func":
        for a in node[2]:
            _refs(a, out)
    elif kind == "neg":
        _refs(node[1], out)
    elif kind == "bin":
        _refs(node[2], out)
        _refs(node[3], out)
    return out


class Sheet:
    def __init__(self):
        self._raw = {}
        self._parsed = {}  # raw formula string -> AST, or None on parse error
        self._values = None  # cell -> value; None means stale

    def set(self, cell, raw):
        _check_cell(cell)
        if raw == "":
            self._raw.pop(cell, None)
        else:
            self._raw[cell] = raw
        self._values = None

    def copy(self, src, dst):
        _check_cell(src)
        _check_cell(dst)
        (sc, sr), (dc, dr) = _split_cell(src), _split_cell(dst)
        dcol, drow = ord(dc) - ord(sc), dr - sr

        def shift(ref):
            cabs, col, rabs, row = ref
            if not cabs:
                col = chr(ord(col) + dcol) if "A" <= chr(ord(col) + dcol) <= "Z" else None
            if not rabs:
                row += drow
            if col is None or not _row_ok(row):
                return None
            return (cabs, col, rabs, row)

        def shift_range(a, b):
            a, b = shift(a), shift(b)
            return None if a is None or b is None else (a, b)

        raw = self._raw.get(src, "")
        if raw.startswith("="):
            raw = rewrite_refs(raw, shift, shift_range)
        self.set(dst, raw)

    def insert_rows(self, at, n):
        _check_rows(at, n)

        def shift(ref):
            cabs, col, rabs, row = ref
            if row >= at:
                row += n
            return (cabs, col, rabs, row) if _row_ok(row) else None

        def shift_range(a, b):
            a, b = shift(a), shift(b)
            return None if a is None or b is None else (a, b)

        def move(row):
            return row + n if row >= at else row

        self._restructure(shift, shift_range, move)

    def delete_rows(self, at, n):
        _check_rows(at, n)
        end = at + n - 1  # last deleted row

        def shift(ref):
            cabs, col, rabs, row = ref
            if at <= row <= end:
                return None
            return (cabs, col, rabs, row - n if row > end else row)

        def shift_range(a, b):
            top, bottom = min(a[3], b[3]), max(a[3], b[3])
            if at <= top and bottom <= end:
                return None
            new_top = top if top < at else (at if top <= end else top - n)
            new_bottom = bottom if bottom < at else (at - 1 if bottom <= end else bottom - n)
            if a[3] <= b[3]:
                rows = new_top, new_bottom
            else:
                rows = new_bottom, new_top
            return (a[:3] + (rows[0],), b[:3] + (rows[1],))

        def move(row):
            if row < at:
                return row
            return None if row <= end else row - n

        self._restructure(shift, shift_range, move)

    def _restructure(self, on_ref, on_range, move_row):
        """Rewrite every formula, then move cells to `move_row(row)`.

        A cell whose new row is None or out of bounds is dropped.
        """
        new = {}
        for cell, raw in self._raw.items():
            col, row = _split_cell(cell)
            row = move_row(row)
            if row is None or not _row_ok(row):
                continue
            if raw.startswith("="):
                raw = rewrite_refs(raw, on_ref, on_range)
            new[f"{col}{row}"] = raw
        self._raw = new
        self._values = None

    def raw(self, cell):
        _check_cell(cell)
        return self._raw.get(cell, "")

    def get(self, cell):
        _check_cell(cell)
        if self._values is None:
            self._recalc()
        return self._values.get(cell)

    # -- evaluation ---------------------------------------------------------

    def _tree(self, raw):
        if raw not in self._parsed:
            try:
                self._parsed[raw] = parse_formula(raw)
            except ParseError:
                self._parsed[raw] = None
        return self._parsed[raw]

    def _deps(self, cell):
        raw = self._raw[cell]
        if not raw.startswith("="):
            return ()
        tree = self._tree(raw)
        if tree is None:
            return ()
        return [c for c in _refs(tree, set()) if c in self._raw]

    def _order(self):
        """Iterative Tarjan: yields SCCs, dependencies before dependents."""
        index, low, on_stack, stack = {}, {}, set(), []
        counter = 0
        for root in self._raw:
            if root in index:
                continue
            work = [(root, iter(self._deps(root)))]
            index[root] = low[root] = counter
            counter += 1
            stack.append(root)
            on_stack.add(root)
            while work:
                node, it = work[-1]
                advanced = False
                for dep in it:
                    if dep not in index:
                        index[dep] = low[dep] = counter
                        counter += 1
                        stack.append(dep)
                        on_stack.add(dep)
                        work.append((dep, iter(self._deps(dep))))
                        advanced = True
                        break
                    if dep in on_stack:
                        low[node] = min(low[node], index[dep])
                if advanced:
                    continue
                work.pop()
                if work:
                    parent = work[-1][0]
                    low[parent] = min(low[parent], low[node])
                if low[node] == index[node]:
                    scc = []
                    while True:
                        c = stack.pop()
                        on_stack.discard(c)
                        scc.append(c)
                        if c == node:
                            break
                    yield scc

    def _recalc(self):
        self._values = {}
        for scc in self._order():
            if len(scc) > 1 or scc[0] in self._deps(scc[0]):
                for cell in scc:
                    self._values[cell] = CYCLE
            else:
                self._values[scc[0]] = self._compute(scc[0])

    def _compute(self, cell):
        raw = self._raw[cell]
        if not raw.startswith("="):
            return _literal(raw)
        tree = self._tree(raw)
        if tree is None:
            return VALUE
        return self._eval(tree)

    def _eval(self, node):
        kind = node[0]
        if kind in ("num", "err"):
            return node[1]
        if kind == "ref":
            col, row = node[1]
            v = self._values.get(f"{col}{row}")
            return 0 if v is None else v
        if kind == "neg":
            v = self._eval(node[1])
            if _is_error(v):
                return v
            if isinstance(v, str):
                return VALUE
            return -v
        if kind == "func":
            return self._call(node[1], node[2])
        _, op, l, r = node
        return _binop(op, self._eval(l), self._eval(r))

    def _call(self, name, args):
        nums = []
        for arg in args:
            if arg[0] == "range":
                for c in _range_cells(arg[1], arg[2]):
                    v = self._values.get(c)
                    if _is_error(v):
                        return v
                    if v is None or isinstance(v, str):
                        continue
                    nums.append(v)
            else:
                v = self._eval(arg)
                if _is_error(v):
                    return v
                if isinstance(v, str):
                    return VALUE
                nums.append(v)
        if name == "COUNT":
            return len(nums)
        if name == "AVG":
            return sum(nums) / len(nums) if nums else DIV0
        if not nums:
            return 0
        if name == "SUM":
            return sum(nums)
        result = min(nums) if name == "MIN" else max(nums)
        if any(isinstance(n, float) for n in nums):
            result = float(result)
        return result

"""Mini spreadsheet engine."""
import re

CELL_RE = re.compile(r"[A-Z][1-9]\d{0,2}")
INT_RE = re.compile(r"-?\d+")
FLOAT_RE = re.compile(r"-?\d+\.\d+")

DIV0 = "#DIV/0!"
VALUE = "#VALUE!"
REF = "#REF!"
CYCLE = "#CYCLE!"
ERRORS = frozenset({DIV0, VALUE, REF, CYCLE})
FUNCTIONS = frozenset({"SUM", "MIN", "MAX", "AVG", "COUNT"})

MAX_ROW = 999
REF_PATTERN = r"(?P<cabs>\$?)(?P<col>[A-Z])(?P<rabs>\$?)(?P<row>\d+)"
REF_RE = re.compile(REF_PATTERN)
TOKEN_RE = re.compile(
    r"\s*(?:"
    r"(?P<num>\d+(?:\.\d+)?)"
    r"|(?P<ref>" + REF_PATTERN + r")"
    r"|(?P<ident>[A-Z]+)"
    r"|(?P<err>#REF!)"
    r"|(?P<op>[-+*/(),:])"
    r")"
)


def _check_cell(cell):
    if not isinstance(cell, str) or not CELL_RE.fullmatch(cell):
        raise ValueError(f"invalid cell name: {cell!r}")


def _check_rows(at, n):
    if not (isinstance(at, int) and isinstance(n, int) and 1 <= at <= MAX_ROW and n >= 0):
        raise ValueError(f"invalid row arguments: at={at!r}, n={n!r}")


class ParseError(Exception):
    pass


def tokenize(text):
    tokens = []
    pos = 0
    while True:
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos == len(text):
            break
        m = TOKEN_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ParseError(f"bad token at {pos}")
        if m.group("num"):
            s = m.group("num")
            tokens.append(("num", float(s) if "." in s else int(s)))
        elif m.group("ref"):
            tokens.append(("ref", (m.group("col"), int(m.group("row")))))
        elif m.group("ident"):
            tokens.append(("ident", m.group("ident")))
        elif m.group("err"):
            tokens.append(("err", REF))
        else:
            tokens.append(("op", m.group("op")))
        pos = m.end()
    return tokens


class Parser:
    """Recursive descent parser producing a tuple-based AST."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise ParseError(f"expected {op}")

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise ParseError("trailing tokens")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            return ("ref", val) if _row_ok(val[1]) else ("err", REF)
        if kind == "err":
            return ("err", val)
        if kind == "ident":
            if val not in FUNCTIONS:
                raise ParseError(f"unknown function {val}")
            self.expect_op("(")
            args = []
            if self.peek() != ("op", ")"):
                args.append(self.arg())
                while self.peek() == ("op", ","):
                    self.take()
                    args.append(self.arg())
            self.expect_op(")")
            return ("func", val, args)
        if (kind, val) == ("op", "("):
            node = self.expr()
            self.expect_op(")")
            return node
        raise ParseError("unexpected token")

    def arg(self):
        nxt = self.tokens[self.i + 1] if self.i + 1 < len(self.tokens) else None
        if self.peek()[0] == "ref" and nxt == ("op", ":"):
            a = self.take()[1]
            self.take()
            kind, b = self.take()
            if kind != "ref":
                raise ParseError("bad range")
            if not (_row_ok(a[1]) and _row_ok(b[1])):
                return ("err", REF)
            return ("range", a, b)
        return self.expr()


def _row_ok(row):
    return 1 <= row <= MAX_ROW


def parse_formula(raw):
    return Parser(tokenize(raw[1:])).parse()


def _split_cell(cell):
    return cell[0], int(cell[1:])


def rewrite_refs(formula, on_ref, on_range):
    """Rewrite every reference in `formula` in place.

    `on_ref(ref)` and `on_range(ref1, ref2)` receive parsed references
    (cabs, col, rabs, row). `on_ref` returns a new ref or None; `on_range`
    returns a pair of new refs or None. None becomes `#REF!` (a whole range
    collapses to a single `#REF!`). Everything else in the formula,
    including spacing around a range's colon, is preserved exactly.
    """
    out = []
    pos = 0
    n = len(formula)
    while pos < n:
        m = TOKEN_RE.match(formula, pos)
        if not m or m.end() == pos:
            out.append(formula[pos])
            pos += 1
            continue
        if not m.group("ref"):
            out.append(formula[pos:m.end()])
            pos = m.end()
            continue
        out.append(formula[pos:m.start("ref")])
        ref1 = _ref_parts(m)
        end1 = m.end()
        colon = re.compile(r"\s*:").match(formula, end1)
        m2 = TOKEN_RE.match(formula, colon.end()) if colon else None
        if m2 and m2.group("ref"):
            new = on_range(ref1, _ref_parts(m2))
            if new is None:
                out.append(REF)
            else:
                out.append(format_ref(new[0]))
                out.append(formula[end1:m2.start("ref")])
                out.append(format_ref(new[1]))
            pos = m2.end()
        else:
            new = on_ref(ref1)
            out.append(REF if new is None else format_ref(new))
            pos = end1
    return "".join(out)


def _ref_parts(m):
    return (m.group("cabs"), m.group("col"), m.group("rabs"), int(m.group("row")))


def format_ref(ref):
    cabs, col, rabs, row = ref
    return f"{cabs}{col}{rabs}{row}"


def _is_error(v):
    return isinstance(v, str) and v in ERRORS


def _binop(op, a, b):
    for v in (a, b):
        if _is_error(v):
            return v
    if isinstance(a, str) or isinstance(b, str):
        return VALUE
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return DIV0
    return a / b


def _literal(raw):
    """Value of a non-formula raw."""
    if INT_RE.fullmatch(raw):
        return int(raw)
    if FLOAT_RE.fullmatch(raw):
        return float(raw)
    return raw


def _range_cells(a, b):
    """Cells of a rectangle in row-major order; corners in any order."""
    (c1, r1), (c2, r2) = a, b
    cols = range(min(ord(c1), ord(c2)), max(ord(c1), ord(c2)) + 1)
    return [f"{chr(c)}{r}" for r in range(min(r1, r2), max(r1, r2) + 1) for c in cols]


def _refs(node, out):
    """Collect the cell names a formula AST references."""
    kind = node[0]
    if kind == "ref":
        col, row = node[1]
        out.add(f"{col}{row}")
    elif kind == "range":
        out.update(_range_cells(node[1], node[2]))
    elif kind == "func":
        for a in node[2]:
            _refs(a, out)
    elif kind == "neg":
        _refs(node[1], out)
    elif kind == "bin":
        _refs(node[2], out)
        _refs(node[3], out)
    return out


def _action(method):
    """Make a mutating method one undoable action."""

    @functools.wraps(method)
    def wrapper(self, *args, **kwargs):
        before = dict(self._raw)
        result = method(self, *args, **kwargs)
        self._undo.append(before)
        self._redo.clear()
        return result

    return wrapper


class Sheet:
    def __init__(self):
        self._raw = {}
        self._parsed = {}  # raw formula string -> AST, or None on parse error
        self._values = None  # cell -> value; None means stale
        self._undo = []  # snapshots of _raw before each action
        self._redo = []

    def undo(self):
        if not self._undo:
            return False
        self._redo.append(self._raw)
        self._raw = self._undo.pop()
        self._values = None
        return True

    def redo(self):
        if not self._redo:
            return False
        self._undo.append(self._raw)
        self._raw = self._redo.pop()
        self._values = None
        return True

    @_action
    def set(self, cell, raw):
        self._set(cell, raw)

    def _set(self, cell, raw):
        _check_cell(cell)
        if not isinstance(raw, str):
            raise TypeError("raw must be a str")
        if raw == "":
            self._raw.pop(cell, None)
        else:
            self._raw[cell] = raw
        self._values = None

    def copy(self, src, dst):
        _check_cell(src)
        _check_cell(dst)
        (sc, sr), (dc, dr) = _split_cell(src), _split_cell(dst)
        dcol, drow = ord(dc) - ord(sc), dr - sr

        def shift(ref):
            cabs, col, rabs, row = ref
            if not cabs:
                col = chr(ord(col) + dcol) if "A" <= chr(ord(col) + dcol) <= "Z" else None
            if not rabs:
                row += drow
            if col is None or not _row_ok(row):
                return None
            return (cabs, col, rabs, row)

        def shift_range(a, b):
            a, b = shift(a), shift(b)
            return None if a is None or b is None else (a, b)

        raw = self._raw.get(src, "")
        if raw.startswith("="):
            raw = rewrite_refs(raw, shift, shift_range)
        self.set(dst, raw)

    def insert_rows(self, at, n):
        _check_rows(at, n)

        def shift(ref):
            cabs, col, rabs, row = ref
            if row >= at:
                row += n
            return (cabs, col, rabs, row) if _row_ok(row) else None

        def shift_range(a, b):
            a, b = shift(a), shift(b)
            return None if a is None or b is None else (a, b)

        def move(row):
            return row + n if row >= at else row

        self._restructure(shift, shift_range, move)

    def delete_rows(self, at, n):
        _check_rows(at, n)
        end = at + n - 1  # last deleted row

        def shift(ref):
            cabs, col, rabs, row = ref
            if at <= row <= end:
                return None
            return (cabs, col, rabs, row - n if row > end else row)

        def shift_range(a, b):
            top, bottom = min(a[3], b[3]), max(a[3], b[3])
            if at <= top and bottom <= end:
                return None
            new_top = top if top < at else (at if top <= end else top - n)
            new_bottom = bottom if bottom < at else (at - 1 if bottom <= end else bottom - n)
            if a[3] <= b[3]:
                rows = new_top, new_bottom
            else:
                rows = new_bottom, new_top
            return (a[:3] + (rows[0],), b[:3] + (rows[1],))

        def move(row):
            if row < at:
                return row
            return None if row <= end else row - n

        self._restructure(shift, shift_range, move)

    def _restructure(self, on_ref, on_range, move_row):
        """Rewrite every formula, then move cells to `move_row(row)`.

        A cell whose new row is None or out of bounds is dropped.
        """
        new = {}
        for cell, raw in self._raw.items():
            col, row = _split_cell(cell)
            row = move_row(row)
            if row is None or not _row_ok(row):
                continue
            if raw.startswith("="):
                raw = rewrite_refs(raw, on_ref, on_range)
            new[f"{col}{row}"] = raw
        self._raw = new
        self._values = None

    def raw(self, cell):
        _check_cell(cell)
        return self._raw.get(cell, "")

    def get(self, cell):
        _check_cell(cell)
        if self._values is None:
            self._recalc()
        return self._values.get(cell)

    # -- evaluation ---------------------------------------------------------

    def _tree(self, raw):
        if raw not in self._parsed:
            try:
                self._parsed[raw] = parse_formula(raw)
            except ParseError:
                self._parsed[raw] = None
        return self._parsed[raw]

    def _deps(self, cell):
        raw = self._raw[cell]
        if not raw.startswith("="):
            return ()
        tree = self._tree(raw)
        if tree is None:
            return ()
        return [c for c in _refs(tree, set()) if c in self._raw]

    def _order(self):
        """Iterative Tarjan: yields SCCs, dependencies before dependents."""
        index, low, on_stack, stack = {}, {}, set(), []
        counter = 0
        for root in self._raw:
            if root in index:
                continue
            work = [(root, iter(self._deps(root)))]
            index[root] = low[root] = counter
            counter += 1
            stack.append(root)
            on_stack.add(root)
            while work:
                node, it = work[-1]
                advanced = False
                for dep in it:
                    if dep not in index:
                        index[dep] = low[dep] = counter
                        counter += 1
                        stack.append(dep)
                        on_stack.add(dep)
                        work.append((dep, iter(self._deps(dep))))
                        advanced = True
                        break
                    if dep in on_stack:
                        low[node] = min(low[node], index[dep])
                if advanced:
                    continue
                work.pop()
                if work:
                    parent = work[-1][0]
                    low[parent] = min(low[parent], low[node])
                if low[node] == index[node]:
                    scc = []
                    while True:
                        c = stack.pop()
                        on_stack.discard(c)
                        scc.append(c)
                        if c == node:
                            break
                    yield scc

    def _recalc(self):
        self._values = {}
        for scc in self._order():
            if len(scc) > 1 or scc[0] in self._deps(scc[0]):
                for cell in scc:
                    self._values[cell] = CYCLE
            else:
                self._values[scc[0]] = self._compute(scc[0])

    def _compute(self, cell):
        raw = self._raw[cell]
        if not raw.startswith("="):
            return _literal(raw)
        tree = self._tree(raw)
        if tree is None:
            return VALUE
        return self._eval(tree)

    def _eval(self, node):
        kind = node[0]
        if kind in ("num", "err"):
            return node[1]
        if kind == "ref":
            col, row = node[1]
            v = self._values.get(f"{col}{row}")
            return 0 if v is None else v
        if kind == "neg":
            v = self._eval(node[1])
            if _is_error(v):
                return v
            if isinstance(v, str):
                return VALUE
            return -v
        if kind == "func":
            return self._call(node[1], node[2])
        _, op, l, r = node
        return _binop(op, self._eval(l), self._eval(r))

    def _call(self, name, args):
        nums = []
        for arg in args:
            if arg[0] == "range":
                for c in _range_cells(arg[1], arg[2]):
                    v = self._values.get(c)
                    if _is_error(v):
                        return v
                    if v is None or isinstance(v, str):
                        continue
                    nums.append(v)
            else:
                v = self._eval(arg)
                if _is_error(v):
                    return v
                if isinstance(v, str):
                    return VALUE
                nums.append(v)
        if name == "COUNT":
            return len(nums)
        if name == "AVG":
            return sum(nums) / len(nums) if nums else DIV0
        if not nums:
            return 0
        if name == "SUM":
            return sum(nums)
        result = min(nums) if name == "MIN" else max(nums)
        if any(isinstance(n, float) for n in nums):
            result = float(result)
        return result

"""Mini spreadsheet engine."""
import re

CELL_RE = re.compile(r"[A-Z][1-9]\d{0,2}")
INT_RE = re.compile(r"-?\d+")
FLOAT_RE = re.compile(r"-?\d+\.\d+")

DIV0 = "#DIV/0!"
VALUE = "#VALUE!"
REF = "#REF!"
CYCLE = "#CYCLE!"
ERRORS = frozenset({DIV0, VALUE, REF, CYCLE})
FUNCTIONS = frozenset({"SUM", "MIN", "MAX", "AVG", "COUNT"})

MAX_ROW = 999
REF_PATTERN = r"(?P<cabs>\$?)(?P<col>[A-Z])(?P<rabs>\$?)(?P<row>\d+)"
REF_RE = re.compile(REF_PATTERN)
TOKEN_RE = re.compile(
    r"\s*(?:"
    r"(?P<num>\d+(?:\.\d+)?)"
    r"|(?P<ref>" + REF_PATTERN + r")"
    r"|(?P<ident>[A-Z]+)"
    r"|(?P<err>#REF!)"
    r"|(?P<op>[-+*/(),:])"
    r")"
)


def _check_cell(cell):
    if not isinstance(cell, str) or not CELL_RE.fullmatch(cell):
        raise ValueError(f"invalid cell name: {cell!r}")


def _check_rows(at, n):
    if not (isinstance(at, int) and isinstance(n, int) and 1 <= at <= MAX_ROW and n >= 0):
        raise ValueError(f"invalid row arguments: at={at!r}, n={n!r}")


class ParseError(Exception):
    pass


def tokenize(text):
    tokens = []
    pos = 0
    while True:
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos == len(text):
            break
        m = TOKEN_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ParseError(f"bad token at {pos}")
        if m.group("num"):
            s = m.group("num")
            tokens.append(("num", float(s) if "." in s else int(s)))
        elif m.group("ref"):
            tokens.append(("ref", (m.group("col"), int(m.group("row")))))
        elif m.group("ident"):
            tokens.append(("ident", m.group("ident")))
        elif m.group("err"):
            tokens.append(("err", REF))
        else:
            tokens.append(("op", m.group("op")))
        pos = m.end()
    return tokens


class Parser:
    """Recursive descent parser producing a tuple-based AST."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise ParseError(f"expected {op}")

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise ParseError("trailing tokens")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            return ("ref", val) if _row_ok(val[1]) else ("err", REF)
        if kind == "err":
            return ("err", val)
        if kind == "ident":
            if val not in FUNCTIONS:
                raise ParseError(f"unknown function {val}")
            self.expect_op("(")
            args = []
            if self.peek() != ("op", ")"):
                args.append(self.arg())
                while self.peek() == ("op", ","):
                    self.take()
                    args.append(self.arg())
            self.expect_op(")")
            return ("func", val, args)
        if (kind, val) == ("op", "("):
            node = self.expr()
            self.expect_op(")")
            return node
        raise ParseError("unexpected token")

    def arg(self):
        nxt = self.tokens[self.i + 1] if self.i + 1 < len(self.tokens) else None
        if self.peek()[0] == "ref" and nxt == ("op", ":"):
            a = self.take()[1]
            self.take()
            kind, b = self.take()
            if kind != "ref":
                raise ParseError("bad range")
            if not (_row_ok(a[1]) and _row_ok(b[1])):
                return ("err", REF)
            return ("range", a, b)
        return self.expr()


def _row_ok(row):
    return 1 <= row <= MAX_ROW


def parse_formula(raw):
    return Parser(tokenize(raw[1:])).parse()


def _split_cell(cell):
    return cell[0], int(cell[1:])


def rewrite_refs(formula, on_ref, on_range):
    """Rewrite every reference in `formula` in place.

    `on_ref(ref)` and `on_range(ref1, ref2)` receive parsed references
    (cabs, col, rabs, row). `on_ref` returns a new ref or None; `on_range`
    returns a pair of new refs or None. None becomes `#REF!` (a whole range
    collapses to a single `#REF!`). Everything else in the formula,
    including spacing around a range's colon, is preserved exactly.
    """
    out = []
    pos = 0
    n = len(formula)
    while pos < n:
        m = TOKEN_RE.match(formula, pos)
        if not m or m.end() == pos:
            out.append(formula[pos])
            pos += 1
            continue
        if not m.group("ref"):
            out.append(formula[pos:m.end()])
            pos = m.end()
            continue
        out.append(formula[pos:m.start("ref")])
        ref1 = _ref_parts(m)
        end1 = m.end()
        colon = re.compile(r"\s*:").match(formula, end1)
        m2 = TOKEN_RE.match(formula, colon.end()) if colon else None
        if m2 and m2.group("ref"):
            new = on_range(ref1, _ref_parts(m2))
            if new is None:
                out.append(REF)
            else:
                out.append(format_ref(new[0]))
                out.append(formula[end1:m2.start("ref")])
                out.append(format_ref(new[1]))
            pos = m2.end()
        else:
            new = on_ref(ref1)
            out.append(REF if new is None else format_ref(new))
            pos = end1
    return "".join(out)


def _ref_parts(m):
    return (m.group("cabs"), m.group("col"), m.group("rabs"), int(m.group("row")))


def format_ref(ref):
    cabs, col, rabs, row = ref
    return f"{cabs}{col}{rabs}{row}"


def _is_error(v):
    return isinstance(v, str) and v in ERRORS


def _binop(op, a, b):
    for v in (a, b):
        if _is_error(v):
            return v
    if isinstance(a, str) or isinstance(b, str):
        return VALUE
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return DIV0
    return a / b


def _literal(raw):
    """Value of a non-formula raw."""
    if INT_RE.fullmatch(raw):
        return int(raw)
    if FLOAT_RE.fullmatch(raw):
        return float(raw)
    return raw


def _range_cells(a, b):
    """Cells of a rectangle in row-major order; corners in any order."""
    (c1, r1), (c2, r2) = a, b
    cols = range(min(ord(c1), ord(c2)), max(ord(c1), ord(c2)) + 1)
    return [f"{chr(c)}{r}" for r in range(min(r1, r2), max(r1, r2) + 1) for c in cols]


def _refs(node, out):
    """Collect the cell names a formula AST references."""
    kind = node[0]
    if kind == "ref":
        col, row = node[1]
        out.add(f"{col}{row}")
    elif kind == "range":
        out.update(_range_cells(node[1], node[2]))
    elif kind == "func":
        for a in node[2]:
            _refs(a, out)
    elif kind == "neg":
        _refs(node[1], out)
    elif kind == "bin":
        _refs(node[2], out)
        _refs(node[3], out)
    return out


def _action(method):
    """Make a mutating method one undoable action."""

    @functools.wraps(method)
    def wrapper(self, *args, **kwargs):
        before = dict(self._raw)
        result = method(self, *args, **kwargs)
        self._undo.append(before)
        self._redo.clear()
        return result

    return wrapper


class Sheet:
    def __init__(self):
        self._raw = {}
        self._parsed = {}  # raw formula string -> AST, or None on parse error
        self._values = None  # cell -> value; None means stale
        self._undo = []  # snapshots of _raw before each action
        self._redo = []

    def undo(self):
        if not self._undo:
            return False
        self._redo.append(self._raw)
        self._raw = self._undo.pop()
        self._values = None
        return True

    def redo(self):
        if not self._redo:
            return False
        self._undo.append(self._raw)
        self._raw = self._redo.pop()
        self._values = None
        return True

    @_action
    def set(self, cell, raw):
        self._set(cell, raw)

    def _set(self, cell, raw):
        _check_cell(cell)
        if not isinstance(raw, str):
            raise TypeError("raw must be a str")
        if raw == "":
            self._raw.pop(cell, None)
        else:
            self._raw[cell] = raw
        self._values = None

    @_action
    def copy(self, src, dst):
        _check_cell(src)
        _check_cell(dst)
        (sc, sr), (dc, dr) = _split_cell(src), _split_cell(dst)
        dcol, drow = ord(dc) - ord(sc), dr - sr

        def shift(ref):
            cabs, col, rabs, row = ref
            if not cabs:
                col = chr(ord(col) + dcol) if "A" <= chr(ord(col) + dcol) <= "Z" else None
            if not rabs:
                row += drow
            if col is None or not _row_ok(row):
                return None
            return (cabs, col, rabs, row)

        def shift_range(a, b):
            a, b = shift(a), shift(b)
            return None if a is None or b is None else (a, b)

        raw = self._raw.get(src, "")
        if raw.startswith("="):
            raw = rewrite_refs(raw, shift, shift_range)
        self.set(dst, raw)

    def insert_rows(self, at, n):
        _check_rows(at, n)

        def shift(ref):
            cabs, col, rabs, row = ref
            if row >= at:
                row += n
            return (cabs, col, rabs, row) if _row_ok(row) else None

        def shift_range(a, b):
            a, b = shift(a), shift(b)
            return None if a is None or b is None else (a, b)

        def move(row):
            return row + n if row >= at else row

        self._restructure(shift, shift_range, move)

    def delete_rows(self, at, n):
        _check_rows(at, n)
        end = at + n - 1  # last deleted row

        def shift(ref):
            cabs, col, rabs, row = ref
            if at <= row <= end:
                return None
            return (cabs, col, rabs, row - n if row > end else row)

        def shift_range(a, b):
            top, bottom = min(a[3], b[3]), max(a[3], b[3])
            if at <= top and bottom <= end:
                return None
            new_top = top if top < at else (at if top <= end else top - n)
            new_bottom = bottom if bottom < at else (at - 1 if bottom <= end else bottom - n)
            if a[3] <= b[3]:
                rows = new_top, new_bottom
            else:
                rows = new_bottom, new_top
            return (a[:3] + (rows[0],), b[:3] + (rows[1],))

        def move(row):
            if row < at:
                return row
            return None if row <= end else row - n

        self._restructure(shift, shift_range, move)

    def _restructure(self, on_ref, on_range, move_row):
        """Rewrite every formula, then move cells to `move_row(row)`.

        A cell whose new row is None or out of bounds is dropped.
        """
        new = {}
        for cell, raw in self._raw.items():
            col, row = _split_cell(cell)
            row = move_row(row)
            if row is None or not _row_ok(row):
                continue
            if raw.startswith("="):
                raw = rewrite_refs(raw, on_ref, on_range)
            new[f"{col}{row}"] = raw
        self._raw = new
        self._values = None

    def raw(self, cell):
        _check_cell(cell)
        return self._raw.get(cell, "")

    def get(self, cell):
        _check_cell(cell)
        if self._values is None:
            self._recalc()
        return self._values.get(cell)

    # -- evaluation ---------------------------------------------------------

    def _tree(self, raw):
        if raw not in self._parsed:
            try:
                self._parsed[raw] = parse_formula(raw)
            except ParseError:
                self._parsed[raw] = None
        return self._parsed[raw]

    def _deps(self, cell):
        raw = self._raw[cell]
        if not raw.startswith("="):
            return ()
        tree = self._tree(raw)
        if tree is None:
            return ()
        return [c for c in _refs(tree, set()) if c in self._raw]

    def _order(self):
        """Iterative Tarjan: yields SCCs, dependencies before dependents."""
        index, low, on_stack, stack = {}, {}, set(), []
        counter = 0
        for root in self._raw:
            if root in index:
                continue
            work = [(root, iter(self._deps(root)))]
            index[root] = low[root] = counter
            counter += 1
            stack.append(root)
            on_stack.add(root)
            while work:
                node, it = work[-1]
                advanced = False
                for dep in it:
                    if dep not in index:
                        index[dep] = low[dep] = counter
                        counter += 1
                        stack.append(dep)
                        on_stack.add(dep)
                        work.append((dep, iter(self._deps(dep))))
                        advanced = True
                        break
                    if dep in on_stack:
                        low[node] = min(low[node], index[dep])
                if advanced:
                    continue
                work.pop()
                if work:
                    parent = work[-1][0]
                    low[parent] = min(low[parent], low[node])
                if low[node] == index[node]:
                    scc = []
                    while True:
                        c = stack.pop()
                        on_stack.discard(c)
                        scc.append(c)
                        if c == node:
                            break
                    yield scc

    def _recalc(self):
        self._values = {}
        for scc in self._order():
            if len(scc) > 1 or scc[0] in self._deps(scc[0]):
                for cell in scc:
                    self._values[cell] = CYCLE
            else:
                self._values[scc[0]] = self._compute(scc[0])

    def _compute(self, cell):
        raw = self._raw[cell]
        if not raw.startswith("="):
            return _literal(raw)
        tree = self._tree(raw)
        if tree is None:
            return VALUE
        return self._eval(tree)

    def _eval(self, node):
        kind = node[0]
        if kind in ("num", "err"):
            return node[1]
        if kind == "ref":
            col, row = node[1]
            v = self._values.get(f"{col}{row}")
            return 0 if v is None else v
        if kind == "neg":
            v = self._eval(node[1])
            if _is_error(v):
                return v
            if isinstance(v, str):
                return VALUE
            return -v
        if kind == "func":
            return self._call(node[1], node[2])
        _, op, l, r = node
        return _binop(op, self._eval(l), self._eval(r))

    def _call(self, name, args):
        nums = []
        for arg in args:
            if arg[0] == "range":
                for c in _range_cells(arg[1], arg[2]):
                    v = self._values.get(c)
                    if _is_error(v):
                        return v
                    if v is None or isinstance(v, str):
                        continue
                    nums.append(v)
            else:
                v = self._eval(arg)
                if _is_error(v):
                    return v
                if isinstance(v, str):
                    return VALUE
                nums.append(v)
        if name == "COUNT":
            return len(nums)
        if name == "AVG":
            return sum(nums) / len(nums) if nums else DIV0
        if not nums:
            return 0
        if name == "SUM":
            return sum(nums)
        result = min(nums) if name == "MIN" else max(nums)
        if any(isinstance(n, float) for n in nums):
            result = float(result)
        return result

"""Mini spreadsheet engine."""
import re

CELL_RE = re.compile(r"[A-Z][1-9]\d{0,2}")
INT_RE = re.compile(r"-?\d+")
FLOAT_RE = re.compile(r"-?\d+\.\d+")

DIV0 = "#DIV/0!"
VALUE = "#VALUE!"
REF = "#REF!"
CYCLE = "#CYCLE!"
ERRORS = frozenset({DIV0, VALUE, REF, CYCLE})
FUNCTIONS = frozenset({"SUM", "MIN", "MAX", "AVG", "COUNT"})

MAX_ROW = 999
REF_PATTERN = r"(?P<cabs>\$?)(?P<col>[A-Z])(?P<rabs>\$?)(?P<row>\d+)"
REF_RE = re.compile(REF_PATTERN)
TOKEN_RE = re.compile(
    r"\s*(?:"
    r"(?P<num>\d+(?:\.\d+)?)"
    r"|(?P<ref>" + REF_PATTERN + r")"
    r"|(?P<ident>[A-Z]+)"
    r"|(?P<err>#REF!)"
    r"|(?P<op>[-+*/(),:])"
    r")"
)


def _check_cell(cell):
    if not isinstance(cell, str) or not CELL_RE.fullmatch(cell):
        raise ValueError(f"invalid cell name: {cell!r}")


def _check_rows(at, n):
    if not (isinstance(at, int) and isinstance(n, int) and 1 <= at <= MAX_ROW and n >= 0):
        raise ValueError(f"invalid row arguments: at={at!r}, n={n!r}")


class ParseError(Exception):
    pass


def tokenize(text):
    tokens = []
    pos = 0
    while True:
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos == len(text):
            break
        m = TOKEN_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ParseError(f"bad token at {pos}")
        if m.group("num"):
            s = m.group("num")
            tokens.append(("num", float(s) if "." in s else int(s)))
        elif m.group("ref"):
            tokens.append(("ref", (m.group("col"), int(m.group("row")))))
        elif m.group("ident"):
            tokens.append(("ident", m.group("ident")))
        elif m.group("err"):
            tokens.append(("err", REF))
        else:
            tokens.append(("op", m.group("op")))
        pos = m.end()
    return tokens


class Parser:
    """Recursive descent parser producing a tuple-based AST."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise ParseError(f"expected {op}")

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise ParseError("trailing tokens")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            return ("ref", val) if _row_ok(val[1]) else ("err", REF)
        if kind == "err":
            return ("err", val)
        if kind == "ident":
            if val not in FUNCTIONS:
                raise ParseError(f"unknown function {val}")
            self.expect_op("(")
            args = []
            if self.peek() != ("op", ")"):
                args.append(self.arg())
                while self.peek() == ("op", ","):
                    self.take()
                    args.append(self.arg())
            self.expect_op(")")
            return ("func", val, args)
        if (kind, val) == ("op", "("):
            node = self.expr()
            self.expect_op(")")
            return node
        raise ParseError("unexpected token")

    def arg(self):
        nxt = self.tokens[self.i + 1] if self.i + 1 < len(self.tokens) else None
        if self.peek()[0] == "ref" and nxt == ("op", ":"):
            a = self.take()[1]
            self.take()
            kind, b = self.take()
            if kind != "ref":
                raise ParseError("bad range")
            if not (_row_ok(a[1]) and _row_ok(b[1])):
                return ("err", REF)
            return ("range", a, b)
        return self.expr()


def _row_ok(row):
    return 1 <= row <= MAX_ROW


def parse_formula(raw):
    return Parser(tokenize(raw[1:])).parse()


def _split_cell(cell):
    return cell[0], int(cell[1:])


def rewrite_refs(formula, on_ref, on_range):
    """Rewrite every reference in `formula` in place.

    `on_ref(ref)` and `on_range(ref1, ref2)` receive parsed references
    (cabs, col, rabs, row). `on_ref` returns a new ref or None; `on_range`
    returns a pair of new refs or None. None becomes `#REF!` (a whole range
    collapses to a single `#REF!`). Everything else in the formula,
    including spacing around a range's colon, is preserved exactly.
    """
    out = []
    pos = 0
    n = len(formula)
    while pos < n:
        m = TOKEN_RE.match(formula, pos)
        if not m or m.end() == pos:
            out.append(formula[pos])
            pos += 1
            continue
        if not m.group("ref"):
            out.append(formula[pos:m.end()])
            pos = m.end()
            continue
        out.append(formula[pos:m.start("ref")])
        ref1 = _ref_parts(m)
        end1 = m.end()
        colon = re.compile(r"\s*:").match(formula, end1)
        m2 = TOKEN_RE.match(formula, colon.end()) if colon else None
        if m2 and m2.group("ref"):
            new = on_range(ref1, _ref_parts(m2))
            if new is None:
                out.append(REF)
            else:
                out.append(format_ref(new[0]))
                out.append(formula[end1:m2.start("ref")])
                out.append(format_ref(new[1]))
            pos = m2.end()
        else:
            new = on_ref(ref1)
            out.append(REF if new is None else format_ref(new))
            pos = end1
    return "".join(out)


def _ref_parts(m):
    return (m.group("cabs"), m.group("col"), m.group("rabs"), int(m.group("row")))


def format_ref(ref):
    cabs, col, rabs, row = ref
    return f"{cabs}{col}{rabs}{row}"


def _is_error(v):
    return isinstance(v, str) and v in ERRORS


def _binop(op, a, b):
    for v in (a, b):
        if _is_error(v):
            return v
    if isinstance(a, str) or isinstance(b, str):
        return VALUE
    if op == "+":
        return a + b
    if op == "-":
        return a - b
    if op == "*":
        return a * b
    if b == 0:
        return DIV0
    return a / b


def _literal(raw):
    """Value of a non-formula raw."""
    if INT_RE.fullmatch(raw):
        return int(raw)
    if FLOAT_RE.fullmatch(raw):
        return float(raw)
    return raw


def _range_cells(a, b):
    """Cells of a rectangle in row-major order; corners in any order."""
    (c1, r1), (c2, r2) = a, b
    cols = range(min(ord(c1), ord(c2)), max(ord(c1), ord(c2)) + 1)
    return [f"{chr(c)}{r}" for r in range(min(r1, r2), max(r1, r2) + 1) for c in cols]


def _refs(node, out):
    """Collect the cell names a formula AST references."""
    kind = node[0]
    if kind == "ref":
        col, row = node[1]
        out.add(f"{col}{row}")
    elif kind == "range":
        out.update(_range_cells(node[1], node[2]))
    elif kind == "func":
        for a in node[2]:
            _refs(a, out)
    elif kind == "neg":
        _refs(node[1], out)
    elif kind == "bin":
        _refs(node[2], out)
        _refs(node[3], out)
    return out


def _action(method):
    """Make a mutating method one undoable action."""

    @functools.wraps(method)
    def wrapper(self, *args, **kwargs):
        before = dict(self._raw)
        result = method(self, *args, **kwargs)
        self._undo.append(before)
        self._redo.clear()
        return result

    return wrapper


class Sheet:
    def __init__(self):
        self._raw = {}
        self._parsed = {}  # raw formula string -> AST, or None on parse error
        self._values = None  # cell -> value; None means stale
        self._undo = []  # snapshots of _raw before each action
        self._redo = []

    def undo(self):
        if not self._undo:
            return False
        self._redo.append(self._raw)
        self._raw = self._undo.pop()
        self._values = None
        return True

    def redo(self):
        if not self._redo:
            return False
        self._undo.append(self._raw)
        self._raw = self._redo.pop()
        self._values = None
        return True

    @_action
    def set(self, cell, raw):
        self._set(cell, raw)

    def _set(self, cell, raw):
        _check_cell(cell)
        if not isinstance(raw, str):
            raise TypeError("raw must be a str")
        if raw == "":
            self._raw.pop(cell, None)
        else:
            self._raw[cell] = raw
        self._values = None

    @_action
    def copy(self, src, dst):
        _check_cell(src)
        _check_cell(dst)
        (sc, sr), (dc, dr) = _split_cell(src), _split_cell(dst)
        dcol, drow = ord(dc) - ord(sc), dr - sr

        def shift(ref):
            cabs, col, rabs, row = ref
            if not cabs:
                col = chr(ord(col) + dcol) if "A" <= chr(ord(col) + dcol) <= "Z" else None
            if not rabs:
                row += drow
            if col is None or not _row_ok(row):
                return None
            return (cabs, col, rabs, row)

        def shift_range(a, b):
            a, b = shift(a), shift(b)
            return None if a is None or b is None else (a, b)

        raw = self._raw.get(src, "")
        if raw.startswith("="):
            raw = rewrite_refs(raw, shift, shift_range)
        self._set(dst, raw)

    def insert_rows(self, at, n):
        _check_rows(at, n)

        def shift(ref):
            cabs, col, rabs, row = ref
            if row >= at:
                row += n
            return (cabs, col, rabs, row) if _row_ok(row) else None

        def shift_range(a, b):
            a, b = shift(a), shift(b)
            return None if a is None or b is None else (a, b)

        def move(row):
            return row + n if row >= at else row

        self._restructure(shift, shift_range, move)

    def delete_rows(self, at, n):
        _check_rows(at, n)
        end = at + n - 1  # last deleted row

        def shift(ref):
            cabs, col, rabs, row = ref
            if at <= row <= end:
                return None
            return (cabs, col, rabs, row - n if row > end else row)

        def shift_range(a, b):
            top, bottom = min(a[3], b[3]), max(a[3], b[3])
            if at <= top and bottom <= end:
                return None
            new_top = top if top < at else (at if top <= end else top - n)
            new_bottom = bottom if bottom < at else (at - 1 if bottom <= end else bottom - n)
            if a[3] <= b[3]:
                rows = new_top, new_bottom
            else:
                rows = new_bottom, new_top
            return (a[:3] + (rows[0],), b[:3] + (rows[1],))

        def move(row):
            if row < at:
                return row
            return None if row <= end else row - n

        self._restructure(shift, shift_range, move)

    def _restructure(self, on_ref, on_range, move_row):
        """Rewrite every formula, then move cells to `move_row(row)`.

        A cell whose new row is None or out of bounds is dropped.
        """
        new = {}
        for cell, raw in self._raw.items():
            col, row = _split_cell(cell)
            row = move_row(row)
            if row is None or not _row_ok(row):
                continue
            if raw.startswith("="):
                raw = rewrite_refs(raw, on_ref, on_range)
            new[f"{col}{row}"] = raw
        self._raw = new
        self._values = None

    def raw(self, cell):
        _check_cell(cell)
        return self._raw.get(cell, "")

    def get(self, cell):
        _check_cell(cell)
        if self._values is None:
            self._recalc()
        return self._values.get(cell)

    # -- evaluation ---------------------------------------------------------

    def _tree(self, raw):
        if raw not in self._parsed:
            try:
                self._parsed[raw] = parse_formula(raw)
            except ParseError:
                self._parsed[raw] = None
        return self._parsed[raw]

    def _deps(self, cell):
        raw = self._raw[cell]
        if not raw.startswith("="):
            return ()
        tree = self._tree(raw)
        if tree is None:
            return ()
        return [c for c in _refs(tree, set()) if c in self._raw]

    def _order(self):
        """Iterative Tarjan: yields SCCs, dependencies before dependents."""
        index, low, on_stack, stack = {}, {}, set(), []
        counter = 0
        for root in self._raw:
            if root in index:
                continue
            work = [(root, iter(self._deps(root)))]
            index[root] = low[root] = counter
            counter += 1
            stack.append(root)
            on_stack.add(root)
            while work:
                node, it = work[-1]
                advanced = False
                for dep in it:
                    if dep not in index:
                        index[dep] = low[dep] = counter
                        counter += 1
                        stack.append(dep)
                        on_stack.add(dep)
                        work.append((dep, iter(self._deps(dep))))
                        advanced = True
                        break
                    if dep in on_stack:
                        low[node] = min(low[node], index[dep])
                if advanced:
                    continue
                work.pop()
                if work:
                    parent = work[-1][0]
                    low[parent] = min(low[parent], low[node])
                if low[node] == index[node]:
                    scc = []
                    while True:
                        c = stack.pop()
                        on_stack.discard(c)
                        scc.append(c)
                        if c == node:
                            break
                    yield scc

    def _recalc(self):
        self._values = {}
        for scc in self._order():
            if len(scc) > 1 or scc[0] in self._deps(scc[0]):
                for cell in scc:
                    self._values[cell] = CYCLE
            else:
                self._values[scc[0]] = self._compute(scc[0])

    def _compute(self, cell):
        raw = self._raw[cell]
        if not raw.startswith("="):
            return _literal(raw)
        tree = self._tree(raw)
        if tree is None:
            return VALUE
        return self._eval(tree)

    def _eval(self, node):
        kind = node[0]
        if kind in ("num", "err"):
            return node[1]
        if kind == "ref":
            col, row = node[1]
            v = self._values.get(f"{col}{row}")
            return 0 if v is None else v
        if kind == "neg":
            v = self._eval(node[1])
            if _is_error(v):
                return v
            if isinstance(v, str):
                return VALUE
            return -v
        if kind == "func":
            return self._call(node[1], node[2])
        _, op, l, r = node
        return _binop(op, self._eval(l), self._eval(r))

    def _call(self, name, args):
        nums = []
        for arg in args:
            if arg[0] == "range":
                for c in _range_cells(arg[1], arg[2]):
                    v = self._values.get(c)
                    if _is_error(v):
                        return v
                    if v is None or isinstance(v, str):
                        continue
                    nums.append(v)
            else:
                v = self._eval(arg)
                if _is_error(v):
                    return v
                if isinstance(v, str):
                    return VALUE
                nums.append(v)
        if name == "COUNT":
            return len(nums)
        if name == "AVG":
            return sum(nums) / len(nums) if nums else DIV0
        if not nums:
            return 0
        if name == "SUM":
            return sum(nums)
        result = min(nums) if name == "MIN" else max(nums)
        if any(isinstance(n, float) for n in nums):
            result = float(result)
        return result

"""Mini spreadsheet engine."""
import re

CELL_RE = re.compile(r"[A-Z][1-9]\d{0,2}")
INT_RE = re.compile(r"-?\d+")
FLOAT_RE = re.compile(r"-?\d+\.\d+")

DIV0 = "#DIV/0!"
VALUE = "#VALUE!"
REF = "#REF!"
CYCLE = "#CYCLE!"
ERRORS = frozenset({DIV0, VALUE, REF, CYCLE})
FUNCTIONS = frozenset({"SUM", "MIN", "MAX", "AVG", "COUNT"})

MAX_ROW = 999
REF_PATTERN = r"(?P<cabs>\$?)(?P<col>[A-Z])(?P<rabs>\$?)(?P<row>\d+)"
REF_RE = re.compile(REF_PATTERN)
TOKEN_RE = re.compile(
    r"\s*(?:"
    r"(?P<num>\d+(?:\.\d+)?)"
    r"|(?P<ref>" + REF_PATTERN + r")"
    r"|(?P<ident>[A-Z]+)"
    r"|(?P<err>#REF!)"
    r"|(?P<op>[-+*/(),:])"
    r")"
)


def _check_cell(cell):
    if not isinstance(cell, str) or not CELL_RE.fullmatch(cell):
        raise ValueError(f"invalid cell name: {cell!r}")


def _check_rows(at, n):
    if not (isinstance(at, int) and isinstance(n, int) and 1 <= at <= MAX_ROW and n >= 0):
        raise ValueError(f"invalid row arguments: at={at!r}, n={n!r}")


class ParseError(Exception):
    pass


def tokenize(text):
    tokens = []
    pos = 0
    while True:
        while pos < len(text) and text[pos].isspace():
            pos += 1
        if pos == len(text):
            break
        m = TOKEN_RE.match(text, pos)
        if not m or m.end() == pos:
            raise ParseError(f"bad token at {pos}")
        if m.group("num"):
            s = m.group("num")
            tokens.append(("num", float(s) if "." in s else int(s)))
        elif m.group("ref"):
            tokens.append(("ref", (m.group("col"), int(m.group("row")))))
        elif m.group("ident"):
            tokens.append(("ident", m.group("ident")))
        elif m.group("err"):
            tokens.append(("err", REF))
        else:
            tokens.append(("op", m.group("op")))
        pos = m.end()
    return tokens


class Parser:
    """Recursive descent parser producing a tuple-based AST."""

    def __init__(self, tokens):
        self.tokens = tokens
        self.i = 0

    def peek(self):
        return self.tokens[self.i] if self.i < len(self.tokens) else (None, None)

    def take(self):
        tok = self.peek()
        self.i += 1
        return tok

    def expect_op(self, op):
        if self.take() != ("op", op):
            raise ParseError(f"expected {op}")

    def parse(self):
        node = self.expr()
        if self.i != len(self.tokens):
            raise ParseError("trailing tokens")
        return node

    def expr(self):
        node = self.term()
        while self.peek() in (("op", "+"), ("op", "-")):
            op = self.take()[1]
            node = ("bin", op, node, self.term())
        return node

    def term(self):
        node = self.unary()
        while self.peek() in (("op", "*"), ("op", "/")):
            op = self.take()[1]
            node = ("bin", op, node, self.unary())
        return node

    def unary(self):
        if self.peek() == ("op", "-"):
            self.take()
            return ("neg", self.unary())
        return self.atom()

    def atom(self):
        kind, val = self.take()
        if kind == "num":
            return ("num", val)
        if kind == "ref":
            return ("ref", val) if _row_ok(val[1]) else ("err", REF)
        if kind == "err":
            return ("err", val)
        if kind == "ident":
            if val not in FUNCTIONS:
                raise ParseError(f"unknown function {val}")
            self.expect_op("(")
            args = []
            if self.peek() != ("op", ")"):
                args.append(self.arg())
                while self.peek() == ("op", ","):
                    self.take()
                    args.append(self.arg())
            self.expect_op(")")
            return ("func", val, args)
        if (kind, val) == ("op", "("):
            node = self.expr()
            self.expect_op(")")
            return node
        raise ParseError("unexpected token")

    def arg(self):
        nxt = self.tokens[self.i + 1] if self.i + 1 < len(self.tokens) else None
        if self.peek()[0] == "ref" and nxt == ("op", ":"):
            a = self.take()[1]
            self.take()
            kind, b = self.take()
            if kind != "ref":
                raise ParseError("bad range")
            if not (_row_ok(a[1]) and _row_ok(b[1])):
                return ("err", REF)
            return ("range", a, b)
        return self.expr()


def _row_ok(row):
    return 1 <= row <= MAX_ROW


def parse_formula(raw):
    return Parser(tokenize(raw[1:])).parse()


